import { Suspense } from "react";
import { PromptInput } from "@/components/prompt-input";
import { RecentComparisons } from "@/components/recent-comparisons";

export const metadata = {
  title: "ThinkDiff — Compare LLM Reasoning",
  description: "Visualize and compare reasoning traces from Claude, DeepSeek R1, and OpenAI o3",
};

export default function HomePage() {
  return (
    <main className="min-h-screen flex flex-col">
      {/* Hero Section */}
      <section className="flex-1 flex flex-col items-center justify-center px-6 py-20">
        <h1
          className="text-5xl font-bold text-center mb-4 bg-gradient-to-r from-emerald-400 via-cyan-400 to-purple-400 bg-clip-text text-transparent"
        >
          Compare How AI Thinks
        </h1>
        <p className="text-lg text-muted-foreground text-center max-w-xl mb-10">
          Send the same prompt to Claude, DeepSeek R1, and OpenAI o3.
          See their reasoning side-by-side.
        </p>

        {/* Prompt Input — client island */}
        <div className="w-full max-w-2xl">
          <PromptInput />
        </div>
      </section>

      {/* Recent Comparisons */}
      <section className="px-6 pb-16">
        <h2 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider mb-4">
          Recent Comparisons
        </h2>
        <Suspense fallback={<div className="h-32 animate-pulse bg-white/5 rounded-xl" />}>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="glass rounded-xl p-4 space-y-2 hover:scale-[1.02] transition-transform cursor-pointer"
              >
                <p className="text-sm text-foreground line-clamp-2">
                  Sample prompt {i}...
                </p>
                <div className="flex gap-2">
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-400">Claude</span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-blue-500/20 text-blue-400">DeepSeek</span>
                  <span className="text-[10px] px-1.5 py-0.5 rounded bg-purple-500/20 text-purple-400">o3</span>
                </div>
              </div>
            ))}
          </div>
        </Suspense>
      </section>
    </main>
  );
}

import { create } from "zustand";
import { subscribeWithSelector } from "zustand/middleware";
import type { ParsedTrace, AlignmentResult } from "./parser/types";

type Provider = "claude" | "deepseek" | "openai";
type ComparisonMode = "side-by-side" | "aligned" | "tree";

interface TraceState {
  // Trace data per provider
  traces: Partial<Record<Provider, ParsedTrace>>;
  isLoading: Partial<Record<Provider, boolean>>;
  errors: Partial<Record<Provider, string>>;

  // UI state
  selectedModels: Provider[];
  activePanel: Provider | null;
  comparisonMode: ComparisonMode;
  prompt: string;

  // Derived
  alignment: AlignmentResult | null;

  // Actions
  setPrompt: (prompt: string) => void;
  setTrace: (provider: Provider, trace: ParsedTrace) => void;
  setLoading: (provider: Provider, loading: boolean) => void;
  setError: (provider: Provider, error: string) => void;
  setComparisonMode: (mode: ComparisonMode) => void;
  toggleModel: (provider: Provider) => void;
  setActivePanel: (provider: Provider | null) => void;
  setAlignment: (result: AlignmentResult) => void;
  reset: () => void;
}

export const useTraceStore = create<TraceState>()(
  subscribeWithSelector((set) => ({
    traces: {},
    isLoading: {},
    errors: {},
    selectedModels: ["claude", "deepseek", "openai"],
    activePanel: null,
    comparisonMode: "side-by-side",
    prompt: "",
    alignment: null,

    setPrompt: (prompt) => set({ prompt }),
    setTrace: (provider, trace) =>
      set((s) => ({
        traces: { ...s.traces, [provider]: trace },
        isLoading: { ...s.isLoading, [provider]: false },
      })),
    setLoading: (provider, loading) =>
      set((s) => ({ isLoading: { ...s.isLoading, [provider]: loading } })),
    setError: (provider, error) =>
      set((s) => ({
        errors: { ...s.errors, [provider]: error },
        isLoading: { ...s.isLoading, [provider]: false },
      })),
    setComparisonMode: (comparisonMode) => set({ comparisonMode }),
    toggleModel: (provider) =>
      set((s) => ({
        selectedModels: s.selectedModels.includes(provider)
          ? s.selectedModels.filter((m) => m !== provider)
          : [...s.selectedModels, provider],
      })),
    setActivePanel: (activePanel) => set({ activePanel }),
    setAlignment: (alignment) => set({ alignment }),
    reset: () =>
      set({
        traces: {},
        isLoading: {},
        errors: {},
        prompt: "",
        alignment: null,
        activePanel: null,
      }),
  }))
);

/** Raw trace output from an LLM provider */
export interface RawTrace {
  provider: "claude" | "deepseek" | "openai";
  model: string;
  prompt: string;
  thinkingText: string;
  responseText: string;
  tokensUsed: number;
  latencyMs: number;
}

/** A parsed reasoning phase within a trace */
export interface ReasoningPhase {
  id: string;
  type: PhaseType;
  content: string;
  depth: number;
  parentId: string | null;
  confidence: number;
  tokenCount: number;
}

/** Types of reasoning phases the parser can identify */
export type PhaseType =
  | "hypothesis"
  | "evidence"
  | "analysis"
  | "backtracking"
  | "synthesis"
  | "conclusion"
  | "meta-reasoning";

/** Complete parsed trace with phases and metadata */
export interface ParsedTrace {
  raw: RawTrace;
  phases: ReasoningPhase[];
  rootPhaseIds: string[];
  totalDepth: number;
  backtrackCount: number;
}

/** Result of aligning two traces */
export interface AlignmentResult {
  traceA: ParsedTrace;
  traceB: ParsedTrace;
  alignedPairs: AlignedPair[];
  overallDivergence: number;
}

/** A matched pair of phases from two traces */
export interface AlignedPair {
  phaseA: ReasoningPhase | null;
  phaseB: ReasoningPhase | null;
  similarityScore: number;
  divergenceType: "agreement" | "partial" | "divergent" | "unmatched";
}

/** Metrics computed from a parsed trace */
export interface TraceMetrics {
  totalTokens: number;
  reasoningDepth: number;
  phaseDistribution: Record<PhaseType, number>;
  backtrackRatio: number;
  avgConfidence: number;
}
